import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, String> deliverables = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            deliverables.put(parts[0], parts[1]);
        }
        int m = Integer.parseInt(sc.nextLine().trim());
        List<String[]> tests = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            tests.add(sc.nextLine().trim().split("\\s+"));
        }

        Set<String> referenced = new HashSet<>();
        List<String> noBasis = new ArrayList<>();
        for (String[] test : tests) {
            String basis = test[2];
            if (deliverables.containsKey(basis)) {
                referenced.add(basis);
            } else {
                noBasis.add("NOBASIS " + test[0] + " " + basis);
            }
        }

        List<String> untested = new ArrayList<>();
        for (Map.Entry<String, String> entry : deliverables.entrySet()) {
            if (!referenced.contains(entry.getKey())) {
                untested.add("UNTESTED " + entry.getKey() + " " + entry.getValue());
            }
        }
        Collections.sort(untested);
        Collections.sort(noBasis);

        System.out.println(untested.isEmpty() && noBasis.isEmpty() ? "OK" : "NG");
        untested.forEach(System.out::println);
        noBasis.forEach(System.out::println);
    }
}

