import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, String> vModel = new LinkedHashMap<>();
        vModel.put("単体試験", "製造");
        vModel.put("結合試験", "詳細設計");
        vModel.put("総合試験", "基本設計");
        vModel.put("受入試験", "要件定義");

        int matched = 0;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            String testPhase = parts[0];
            String basis = parts[1];
            String expected = vModel.get(testPhase);
            if (expected == null) {
                System.out.println("UNKNOWN " + testPhase);
            } else if (expected.equals(basis)) {
                matched++;
                System.out.println("OK " + testPhase);
            } else {
                System.out.println("NG " + testPhase + " " + expected);
            }
        }
        System.out.println("適合 " + matched + "/" + n);
    }
}
